from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            moves = 0
            pre_visits = 0  # visits already given to current index by bounces from the left

            for i in range(n - 1):
                need = (target + points[i] - 1) // points[i]
                extra = max(0, need - pre_visits)

                if extra == 0:
                    moves += 1
                    pre_visits = 0
                else:
                    moves += 2 * extra - 1
                    pre_visits = extra - 1

                if moves > m:
                    return False

            need = (target + points[-1] - 1) // points[-1]
            extra = max(0, need - pre_visits)
            if extra > 0:
                moves += 2 * extra - 1

            return moves <= m

        lo, hi = 0, min(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
